What does this print?

```go
type C struct{ n int }

func (c C) IncV()  { c.n++ }
func (c *C) IncP() { c.n++ }

func main() {
	x := C{}
	x.IncV()
	x.IncP()
	x.IncP()
	fmt.Println(x.n)
}
```

What does this print?

```go
type Base struct{ Name string }

func (Base) Hello() string { return "base" }

type Derived struct {
	Base
	Name string
}

func (Derived) Hello() string { return "derived" }

func main() {
	d := Derived{Base{"b"}, "d"}
	fmt.Println(d.Name, d.Base.Name, d.Hello(), d.Base.Hello())
}
```
